 public function verificaPrilegio($currentForm)
  { 
  	$usuariologuiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	if(!$this->getUser()->checkPerm($currentForm, $usuariologuiado)){
		$this->redirect(sfConfig::get('base_simad').'/no_autorizado.html');
	}
	 
  }
  public function verificaPrilegioCerrar($currentForm)
  { 
 	$usuarioLoguiado = $this->getUser()->getAttribute('usuario_id', '', 'subscriber');
	if(!$this->getUser()->checkPerm($currentForm, $usuarioLoguiado)){
		$this->redirect(sfConfig::get('base_simad').'/no_autorizado.html');
	}
	 	  
  }

  public function executeList()
  { 
  	$this->verificaPrilegio("autorizacion/list");
    //*************************************************************************************************************/
    $c = new Criteria();
    $c->setDistinct();
    //*************************************************************************************************************/
    $this->parametros = '';
	$usuariologuiado=$this->getUser()->getAttribute('usuario_id','', 'subscriber');	
	//*************************************************************************************************************/
    if($this->getRequestParameter('userAutoriza')){
	  $c->addJoin(AutorizacionComPeer::AUTORIZACIONCOM_ID,AutcomUsuarioPeer::AUTORIZACIONCOM_ID);	      	
	  $c->add(AutcomUsuarioPeer::USUARIO_ID,$this->getRequestParameter('userAutoriza'));
	  $c->add(AutcomUsuarioPeer::ROLAUTCOMUSUARIO_ID,1); 	
	  $this->parametros.="&userAutoriza=".$this->getRequestParameter('userAutoriza');
	}
	//*************************************************************************************************************/
    if($this->getRequestParameter('userAutorizado')){
	  $c->addJoin(AutorizacionComPeer::AUTORIZACIONCOM_ID,AutcomUsuarioPeer::AUTORIZACIONCOM_ID);	      	
	  $c->add(AutcomUsuarioPeer::USUARIO_ID,$this->getRequestParameter('userAutorizado'));
	  $c->add(AutcomUsuarioPeer::ROLAUTCOMUSUARIO_ID,2); 	
	  $this->parametros.="&userAutorizado=".$this->getRequestParameter('userAutorizado');
	}	
	//*************************************************************************************************************/
	if ($this->getRequestParameter('fechaInicial')) {
		if ($this->getRequestParameter('fechaFinal')) {
	        $c->add(AutorizacionComPeer::FECHA_INICIAL_AUT_COM,$this->getRequestParameter('fechaInicial').' 00:00:00',Criteria::GREATER_THAN);
	        $c->addAnd(AutorizacionComPeer::FECHA_FINAL_AUT_COM,$this->getRequestParameter('fechaFinal').' 23:59:59',Criteria::LESS_THAN);
	        $parametros .= "&fechaInicial=" . $this->getRequestParameter('fechaInicial');
	     }else{
		    $c->add(AutorizacionComPeer::FECHA_INICIAL_AUT_COM,$this->getRequestParameter('fechaInicial').' 00:00:00',Criteria::GREATER_THAN);
		    $parametros .= "&fechaInicial=" . $this->getRequestParameter('fechaInicial');
	     }
	 }
	 $c->addJoin(AutorizacionComPeer::AUTORIZACIONCOM_ID,AutcomUsuarioPeer::AUTORIZACIONCOM_ID);
	 $c->addJoin(AutcomUsuarioPeer::USUARIO_ID,UsuarioPeer::USUARIO_ID);	      	
	 //$c->add(AutcomUsuarioPeer::USUARIO_ID,$this->getRequestParameter('userAutorizado'));
	 //$c->addDescendingOrderByColumn(AutcomUsuarioPeer::USUARIO_ID);
	 $c->addDescendingOrderByColumn(AutorizacionComPeer::AUTORIZACIONCOM_ID);
	//**************************************************************************************************************/
	$pager=new sfPropelPager('AutorizacionCom',10);
	$pager->setCriteria($c);
	$pager->setPage($this->getRequestParameter('page',1));
	$pager->init();	
	$this->pager=$pager; 
	//**************************************************************************************************************
	$userAutoriza    = array();
	$userAutorizado  = array();
	foreach($pager->getResults() as $temp){
		$a = new Criteria();
		$a->add(AutcomUsuarioPeer::AUTORIZACIONCOM_ID,$temp->getAutorizacioncomId());
		$a->add(AutcomUsuarioPeer::ROLAUTCOMUSUARIO_ID,1);
		$result =  AutcomUsuarioPeer::doSelectOne($a);
		$userAutoriza[] = $result->getUsuario();
	    //*********************************************************************************************************	
		$b = new Criteria();
		$b->add(AutcomUsuarioPeer::AUTORIZACIONCOM_ID,$temp->getAutorizacioncomId());
		$b->add(AutcomUsuarioPeer::ROLAUTCOMUSUARIO_ID,2);
		$resp =  AutcomUsuarioPeer::doSelectOne($b);
		$userAutorizado[] = $resp->getUsuario();
	}
	$this->userAutorizado = $userAutorizado;
	$this->userAutoriza   = $userAutoriza;
    //*************************************************************************************************************
  }

