  public function executeUpdate()
  {
    if (!$this->getRequestParameter('autorizacioncom_id'))
    {
      $autorizacion_com = new AutorizacionCom();
    }
    else
    {
      $autorizacion_com = AutorizacionComPeer::retrieveByPk($this->getRequestParameter('autorizacioncom_id'));
      $this->forward404Unless($autorizacion_com);
    }

    //$autorizacion_com->setAutorizacioncomId($this->getRequestParameter('autorizacioncom_id'));
    if ($this->getRequestParameter('fecha_inicial_aut_com'))
    { 
	    $autorizacion_com->setFechaInicialAutCom($this->getRequestParameter('fecha_inicial_aut_com').date("G:i:s"));	           
    }else{
		$autorizacion_com->setFechaInicialAutCom(date("Y-m-d G:i:s"));
	}
    if ($this->getRequestParameter('fecha_final_aut_com'))
    {      
      $autorizacion_com->setFechaFinalAutCom($this->getRequestParameter('fecha_final_aut_com').date("G:i:s"));  	       
    }else{
		$autorizacion_com->setFechaFinalAutCom(date("Y-m-d G:i:s"));
	}
    
    $autoriza    = $this->getRequestParameter('userAutoriza');
    $autorizado  = $this->getRequestParameter('userAutorizado');
    $dependencia = $this->getRequestParameter('dependencia_id');
    $autorizacion_com->save();
    /**************************************************************************************************************/    					
    $this->addAutorizacion($autoriza,$autorizado,$autorizacion_com->getAutorizacioncomId());
	/**************************************************************************************************************/
    if($dependencia){    					 
		$c = new Criteria();
		$c->add(UsuarioPeer::DEPENDENCIA_ID,$dependencia);
		$result = UsuarioPeer::doSelect($c);
		foreach($result as $resp){
			if($autorizado != $resp->getUsuarioId()){
				$copia_auto = $autorizacion_com->copy();
		  		$copia_auto->save();
		  		$this->addAutorizacion($autoriza,$resp->getUsuarioId(),$copia_auto->getAutorizacioncomId());
			}	
		}				
	}
	/**************************************************************************************************************/	    
    //return $this->redirect($this->getRequest()->getScriptName().'/autorizacion/show?autorizacioncom_id='.$autorizacion_com->getAutorizacioncomId());
    return $this->redirect($this->getRequest()->getScriptName().'/autorizacion/list');
  }
  
  public function addAutorizacion($idAutoriza, $idAutorizado, $idRegistro)
  {
  	/*******************************************************************************************************/
  	$autorizacion  = new AutcomUsuario();
  	$autorizacion->setUsuarioId($idAutoriza);
  	$autorizacion->setRolautcomusuarioId(1);
	$autorizacion->setAutorizacioncomId($idRegistro);
	$autorizacion->save();    	
  	/*******************************************************************************************************/
	$autorizacion1  = new AutcomUsuario();
  	$autorizacion1->setUsuarioId($idAutorizado);
  	$autorizacion1->setRolautcomusuarioId(2);
	$autorizacion1->setAutorizacioncomId($idRegistro);
	$autorizacion1->save();
	/*******************************************************************************************************/   
  }	 
  public function executeDelete()
  {
  	$autorizacion_com = AutorizacionComPeer::retrieveByPk($this->getRequestParameter('autorizacioncom_id'));
  	//*******************************************************************************************************/
	$conexion = Propel::getConnection();
  	$set = "DELETE FROM %s WHERE AUTORIZACIONCOM_ID = %s;";
	$sql = sprintf($set, AutcomUsuarioPeer::TABLE_NAME,$autorizacion_com->getAutorizacioncomId());    
    $sentencia = $conexion->prepare($sql);
    $sentencia->execute();
	//*******************************************************************************************************/
    $this->forward404Unless($autorizacion_com);
    $autorizacion_com->delete();
    return $this->redirect($this->getRequest()->getScriptName().'/autorizacion/anular');
  }    
